function reportsView() { return kpis()+`<div class="dashboard-mid" style="grid-template-columns:minmax(0,1fr)">${funnel()}</div>`+departmentProgress(); }
function settingsView() {
  return `<div class="settings-grid"><section class="panel settings-card"><h2>${t('Preferences')}</h2><p>${t('Make the workspace yours.')}</p><div class="setting-row"><div><strong>${t('Interface language')}</strong><small>English / Tiếng Việt</small></div><button class="button secondary small" data-action="language">${icon('Globe2')}${state.lang==='en'?'English':'Tiếng Việt'}${icon('ChevronDown')}</button></div><div class="setting-row"><div><strong>${t('Compact layout')}</strong><small>${t('A little more information in the same space.')}</small></div><button class="toggle" data-action="compact" role="switch" aria-checked="${state.compact}" aria-label="${t('Compact layout')}"><span></span></button></div><div class="setting-row"><div><strong>${t('Interview reminders')}</strong><small>${t('Keep your team ready for every conversation.')}</small></div><button class="toggle" data-action="reminders" role="switch" aria-checked="${state.reminders}" aria-label="${t('Interview reminders')}"><span></span></button></div></section><section class="panel settings-card"><h2>${t('Preview workspace')}</h2><p>${t('Explore freely. Changes stay in this browser tab.')}</p><div class="profile-header">${avatar({initials:'TV'},'xl')}<div><h3>Tuấn Vũ</h3><p>${t('Workspace admin')}</p></div></div><div class="detail-row"><span>${icon('Building2')}${t('Workspace')}</span><strong>SuperNet</strong></div><div class="detail-row"><span>${icon('Globe2')}${t('Language')}</span><strong>${state.lang==='en'?'English':'Tiếng Việt'}</strong></div></section></div>`;
}
function emptyState(iconName,title,description) { return `<div class="panel empty-state">${icon(iconName)}<h3>${t(title)}</h3><p>${t(description)}</p></div>`; }
function popover() {
  if(!state.popover)return '';
  if(state.popover==='profile')return `<section class="popover" role="region" aria-label="Profile preferences"><h3>Tuấn Vũ <span class="tag gray" style="margin-left:7px">${t('Workspace admin')}</span></h3><button class="popover-option" data-action="language">${icon('Globe2')}<span>${t('Language')}</span><span>${state.lang==='en'?'English → Tiếng Việt':'Tiếng Việt → English'}</span></button><button class="popover-option" data-action="nav" data-view="settings">${icon('Settings2')}<span>${t('Manage preferences')}</span>${icon('ChevronRight')}</button></section>`;
  return `<section class="popover" role="region" aria-label="${t('Notifications')}"><h3>${t('Notifications')}</h3><div class="notification-item"><span class="kpi-icon">${icon('CalendarDays')}</span><div><strong>Sales Admin · 14:00</strong><p>Lê Phương Linh · ${t('Up next')}</p></div></div><div class="notification-item"><span class="kpi-icon amber">${icon('MessageSquareText')}</span><div><strong>${pendingFeedback().length} ${t('Waiting Feedback')}</strong><p>${t('Close the loop on your team’s interviews.')}</p></div></div><button class="link-button" data-action="nav" data-view="feedback" style="margin-top:10px">${t('Waiting Feedback')}${icon('ArrowRight')}</button></section>`;
}
function render() {
  const views={dashboard,jobs:jobView,candidates:candidatesView,talent:talentView,pipeline:pipelineView,calendar:()=>calendarView(false),feedback:feedbackView,history:()=>calendarView(true),reports:reportsView,settings:settingsView};
  document.documentElement.lang=state.lang==='vi'?'vi':'en';
  document.body.classList.toggle('compact',state.compact);
  $('#app').innerHTML=sidebar()+`<div class="main-shell">${topbar()}<main class="content" id="main-content">${heading()}${views[state.view]()}<footer class="footer"><span>${icon('CircleCheck')}${t('Illustrative data')} · <strong>${t('SuperNet design preview')}</strong></span><span>${t('All times GMT+7')}</span></footer></main>${popover()}</div>`;
  document.title=`SuperNet · ${t(titleFor[state.view])}`;
  bindCharts(); bindDragDrop();
}
function navigate(view) { state.view=view;state.mobileNav=false;state.popover='';hideTooltip();render();window.scrollTo({top:0,behavior:'instant'}); }
function showDialog(title,body,footer='',drawer=false) {
  const dialog=$('#preview-dialog'); if(dialog.open)dialog.close();
  dialog.className=drawer?'drawer':'';
  dialog.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="${t('Close')}">${icon('X')}</button></div>${body}${footer?`<div class="dialog-actions">${footer}</div>`:''}`;
  dialog.showModal();
}
function toast(message) { const el=$('#toast');el.innerHTML=icon('CircleCheck')+`<span>${escapeHtml(message)}</span>`;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{el.hidden=true;},3500); }
function profileForName(name) { return state.candidates.find(item=>item.name===name)||{name,initials:name.split(' ').slice(-2).map(x=>x[0]).join(''),tone:'',role:state.interviews.find(x=>x.name===name)?.role||'Candidate',department:'Marketing',stage:2,saved:false,id:''}; }
